def generate_bibd():
    points = list(range(1, 16))
    lines = []
    for i in range(1, 16):
        for j in range(i + 1, 16):
            k = i ^ j
            if k > j:
                lines.append((i, j, k))

    assert len(lines) == 35

    # Create incidence matrix for BIBD(15, 3, 1)
    matrix_1 = [[0] * 35 for _ in range(15)]
    for col_idx, line in enumerate(lines):
        for pt in line:
            matrix_1[pt - 1][col_idx] = 1

    # Repeat 3 times to get BIBD(15, 3, 3)
    matrix_3 = []
    for row in matrix_1:
        matrix_3.append(row * 3)

    # Verify properties
    assert len(matrix_3) == 15
    assert len(matrix_3[0]) == 105

    for row in matrix_3:
        assert sum(row) == 21

    for col in range(105):
        col_sum = sum(matrix_3[row][col] for row in range(15))
        assert col_sum == 3

    for r1 in range(15):
        for r2 in range(r1 + 1, 15):
            dot = sum(matrix_3[r1][c] * matrix_3[r2][c] for c in range(105))
            assert dot == 3

    flat_list = [val for row in matrix_3 for val in row]
    print(flat_list[:20])
    print(len(flat_list))

    with open("solution.txt", "w") as f:
        f.write(str(flat_list))

